import{_ as e,o as i,c as l,a0 as s}from"./chunks/framework.DhQjJcnt.js";const k=JSON.parse('{"title":"故障排查 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1787985369000}'),o={name:"faq.md"};function t(d,a,r,h,n,c){return i(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="故障排查-faq" tabindex="-1">故障排查 FAQ <a class="header-anchor" href="#故障排查-faq" aria-label="Permalink to &quot;故障排查 FAQ&quot;">​</a></h1><h2 id="连接类问题" tabindex="-1">连接类问题 <a class="header-anchor" href="#连接类问题" aria-label="Permalink to &quot;连接类问题&quot;">​</a></h2><h3 id="访客提示-room-not-found-or-expired-xxx" tabindex="-1">访客提示 <code>room not found or expired: xxx</code> <a class="header-anchor" href="#访客提示-room-not-found-or-expired-xxx" aria-label="Permalink to &quot;访客提示 `room not found or expired: xxx`&quot;">​</a></h3><ul><li>房间号输入有误（区分大小写）</li><li>房间已过期（默认 12 小时）或被房主 Ctrl-C 关闭</li><li>让房主重新 <code>game create</code> 获取新房间号</li></ul><h3 id="访客提示-udp-echo-timed-out" tabindex="-1">访客提示 <code>UDP echo timed out</code> <a class="header-anchor" href="#访客提示-udp-echo-timed-out" aria-label="Permalink to &quot;访客提示 `UDP echo timed out`&quot;">​</a></h3><p>客户端无法与服务器的 UDP 探测端口通信：</p><ul><li>检查服务器 <code>8080/udp</code> 是否放行（云安全组 + 系统防火墙都要）</li><li>检查配置 <code>signaling_addr</code> 是否指向正确服务器</li><li>用 <code>nc -u 服务器IP 8080</code> 或任意 UDP 客户端发 <code>ECHO test</code> 验证回显</li></ul><h3 id="一直-udp-hole-punching-failed-falling-back-to-relay" tabindex="-1">一直 <code>UDP hole punching failed, falling back to relay ...</code> <a class="header-anchor" href="#一直-udp-hole-punching-failed-falling-back-to-relay" aria-label="Permalink to &quot;一直 `UDP hole punching failed, falling back to relay ...`&quot;">​</a></h3><p>打洞失败属正常现象（NAT 过于严格），会自动转中继且<strong>不影响使用</strong>。若希望直连：</p><ul><li>尝试增大 <code>--spread</code>（对称 NAT 场景）</li><li>双方都保证 UDP 出站可用</li><li>若两端在同一局域网/同一 NAT 后，公网打洞属 hairpin 场景，直连可能失败——改用 <code>--relay</code></li></ul><h3 id="双方直连成功但数据不通-客户端连不上-连上没响应" tabindex="-1">双方直连成功但数据不通（客户端连不上/连上没响应） <a class="header-anchor" href="#双方直连成功但数据不通-客户端连不上-连上没响应" aria-label="Permalink to &quot;双方直连成功但数据不通（客户端连不上/连上没响应）&quot;">​</a></h3><ul><li>确认房主 <code>--service</code> 指向的服务<strong>正在运行</strong>且监听正确端口</li><li>确认访客 <code>--listen</code> 端口未被占用</li><li>用 <code>--verbose</code> 查看帧日志是否在收发</li></ul><h3 id="decryption-failed-wrong-key" tabindex="-1"><code>decryption failed (wrong --key?)</code> <a class="header-anchor" href="#decryption-failed-wrong-key" aria-label="Permalink to &quot;`decryption failed (wrong --key?)`&quot;">​</a></h3><p>双方 <code>--key</code> 口令不一致（或有一方没带）。统一口令后重开房间。</p><h2 id="部署类问题" tabindex="-1">部署类问题 <a class="header-anchor" href="#部署类问题" aria-label="Permalink to &quot;部署类问题&quot;">​</a></h2><h3 id="服务器启动报端口占用" tabindex="-1">服务器启动报端口占用 <a class="header-anchor" href="#服务器启动报端口占用" aria-label="Permalink to &quot;服务器启动报端口占用&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AddrInUse</span></span></code></pre></div><ul><li><code>8080</code> 或 <code>8081</code> 被其他进程占用，换端口：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:9000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relay-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:9001</span></span></code></pre></div></li><li>客户端配置相应改为 <code>http://IP:9000</code> 与 <code>IP:9001</code></li></ul><h3 id="windows-上快速重启服务器报「权限不允许的套接字尝试」" tabindex="-1">Windows 上快速重启服务器报「权限不允许的套接字尝试」 <a class="header-anchor" href="#windows-上快速重启服务器报「权限不允许的套接字尝试」" aria-label="Permalink to &quot;Windows 上快速重启服务器报「权限不允许的套接字尝试」&quot;">​</a></h3><p>Windows 下刚关闭的 TCP 监听端口会短暂处于过渡态，立即用同端口绑定 UDP 可能失败：</p><ul><li>等待 2~3 秒再启动</li><li>或让 UDP 探测使用独立端口（<code>signaling_udp</code> + 服务器独立监听）</li></ul><h2 id="性能与稳定性问题" tabindex="-1">性能与稳定性问题 <a class="header-anchor" href="#性能与稳定性问题" aria-label="Permalink to &quot;性能与稳定性问题&quot;">​</a></h2><h3 id="传输慢" tabindex="-1">传输慢 <a class="header-anchor" href="#传输慢" aria-label="Permalink to &quot;传输慢&quot;">​</a></h3><ul><li>可靠流窗口为 32 帧 × 1200B ≈ 38KB 在途；高延迟链路吞吐有限</li><li>若经中继，带宽受服务器出口限制</li><li>打洞直连一般比中继快（少一跳服务器）</li></ul><h3 id="长空闲后连接失效" tabindex="-1">长空闲后连接失效 <a class="header-anchor" href="#长空闲后连接失效" aria-label="Permalink to &quot;长空闲后连接失效&quot;">​</a></h3><p>NAT 映射有超时（通常 30~120s）。frp-sh 每秒互发 keepalive ACK 帧保活，正常不会失效；若你的 NAT 超时极短，可保持低频数据流动。</p><h3 id="大流量时读缓冲丢弃帧" tabindex="-1">大流量时读缓冲丢弃帧 <a class="header-anchor" href="#大流量时读缓冲丢弃帧" aria-label="Permalink to &quot;大流量时读缓冲丢弃帧&quot;">​</a></h3><p>读缓冲上限 1MB，超过后丢弃帧并依赖重传（go-back-N 流控），属预期行为，不影响正确性。</p><h2 id="安全类问题" tabindex="-1">安全类问题 <a class="header-anchor" href="#安全类问题" aria-label="Permalink to &quot;安全类问题&quot;">​</a></h2><h3 id="中继模式数据安全吗" tabindex="-1">中继模式数据安全吗？ <a class="header-anchor" href="#中继模式数据安全吗" aria-label="Permalink to &quot;中继模式数据安全吗？&quot;">​</a></h3><p>中继通道为<strong>明文中转</strong>（数据经过你的信令服务器）。需要机密性时：</p><ul><li>优先使用打洞直连 + <code>--key</code></li><li>或自行在信令服务器前部署加密隧道（如 WireGuard）</li></ul><h3 id="房间号会被别人猜中吗" tabindex="-1">房间号会被别人猜中吗？ <a class="header-anchor" href="#房间号会被别人猜中吗" aria-label="Permalink to &quot;房间号会被别人猜中吗？&quot;">​</a></h3><p>房间号主体为 6 位十六进制（约 1600 万组合）+ 12 小时 TTL，暴力扫描需在短时间访问服务器 1600 万次——低风险但非零。需要更高安全时：</p><ul><li>使用长前缀自定义房间号，如 <code>frp-sh game create --prefix my-long-room-2024</code></li><li>配合 <code>--key</code> 加密（即使房间号泄露，无口令也无法解密）</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="invalid-room-id-校验规则" tabindex="-1"><code>invalid room id</code> 校验规则 <a class="header-anchor" href="#invalid-room-id-校验规则" aria-label="Permalink to &quot;`invalid room id` 校验规则&quot;">​</a></h3><p>房间号格式为 <code>前缀-6位hex</code>（如 <code>game-a3f9c2</code>）。<code>--prefix</code> 仅保留小写字母数字与 <code>-_</code>，最长 16 字符。</p><h3 id="会话怎么结束" tabindex="-1">会话怎么结束？ <a class="header-anchor" href="#会话怎么结束" aria-label="Permalink to &quot;会话怎么结束？&quot;">​</a></h3><p>房主/访客 <code>Ctrl-C</code>；或 <code>--max-conns</code> 用尽自动结束。房主退出会删除房间。</p><h3 id="支持-ipv6-吗" tabindex="-1">支持 IPv6 吗？ <a class="header-anchor" href="#支持-ipv6-吗" aria-label="Permalink to &quot;支持 IPv6 吗？&quot;">​</a></h3><p>信令、中继、打洞均使用标准 <code>SocketAddr</code>，支持 IPv6 地址（配置中写 <code>[::1]:8080</code> 形式）。打洞与 NAT 行为以实际网络环境为准。</p><h3 id="可以在-docker-里跑吗" tabindex="-1">可以在 Docker 里跑吗？ <a class="header-anchor" href="#可以在-docker-里跑吗" aria-label="Permalink to &quot;可以在 Docker 里跑吗？&quot;">​</a></h3><p>可以。静态二进制可直接放入镜像：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ubuntu:24.04</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> frp-sh /usr/local/bin/frp-sh</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 8080/tcp 8080/udp 8081/tcp</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;frp-sh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;serve&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:8080&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--relay-addr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:8081&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><p>遇到文档未覆盖的问题，附上 <code>frp-sh --verbose</code> 的输出与网络环境描述反馈。</p>',47)])])}const u=e(o,[["render",t]]);export{k as __pageData,u as default};
